def compare_builds(a, b):
    """比较形如 "v7" 的构建号：a>b 返回 1，相等返回 0，a<b 返回 -1。"""
    if a > b:
        return 1
    if a < b:
        return -1
    return 0

verification_tests:
from target import compare_builds

def test_small_equal():
